286	
287	        else if (waterLevel> minWaterLevel){
288	            if(weather.getBrightness() > 0.9 && waterLevel > minWaterLevel + 1){
289	                waterLevel -=2;
290	            }
291	            else {
292	                waterLevel -= 1;
